        camera.right = paneW / 2;
        camera.top = paneH / 2;
        camera.bottom = -paneH / 2;
        camera.position.set(0, 0, 8);
        camera.lookAt(0, 0, 0);
        camera.updateProjectionMatrix();
        camera.updateMatrixWorld();
