            // Retiring an old owner cannot remove the replacement's target.
            if (owners.length) controlTargets.set(name, owners.at(-1));
            else controlTargets.delete(name);
          };
        },
        get handLayout() {
          return handLayout;
        },
        get relicLayout() {
          return relicLayout;
        },
        face,
        reduced,
        materials: { chrome, gold, ceramic, black, spectralCrystal },
      });
      return {
        outputs: () => ({
          scene: sceneResource,
          contact: [contact.x, contact.y, fieldImpulse],
          phase,
          eyePointer: [cursorX, cursorPresent ? 1 : 0, reduced.matches ? 1 : 0],
          handTouch: [
            hoverKind === 'heart' ? 1 : 0,
            held?.kind === 'heart' ? 1 : 0,
            reduced.matches ? 1 : 0,
          ],
          handGesture: [
            previewHeart?.scatter ?? 0,
            previewHeart?.grainSize ?? 0,
            previewHeart ? 1 : 0,
          ],
          haloTouch: [
            hoverKind === 'halo' ? 1 : 0,
            held?.kind === 'halo' ? 1 : 0,
            reduced.matches ? 1 : 0,
          ],
          haloGesture: [previewHalo?.mix ?? 0, previewHalo?.afterimage ?? 0, previewHalo ? 1 : 0],
          creatureTouch: [
            hoverKind === 'crab' ? 1 : 0,
            held?.kind === 'crab' ? 1 : 0,
            reduced.matches ? 1 : 0,
          ],
          creatureGesture: [previewCrab?.edge ?? 0, previewCrab?.heat ?? 0, previewCrab ? 1 : 0],
        }),
        update: advance,
        render() {
          renderer.render(scene, camera);
          face.dataset.drawCalls = renderer.info.render.calls;
          face.dataset.frame = frame++;
        },
        dispose() {
          unsubscribe();
          disposed = true;
          observer.disconnect();
          panel.dispose();
          releaseEnvironmentScene();
          for (const resource of resources) resource.dispose();
          key.shadow.dispose();
          renderer.dispose();
          renderer.forceContextLoss();
          face.remove();
        },
      };
    },
  };
}

import * as THREE from 'three';

// One field object, in the same lit scene as Nacre's enclosure and controls.
// Its named graph inputs own the response; geometry and shaders remain authored.
export default function standingWaveField() {
  return {
    create(api) {
      const scene = api.resource('scene');
