        const angle = (i / 80) * Math.PI * 2;
        const tick = new THREE.Mesh(
          keep(new THREE.BoxGeometry(i % 5 === 0 ? 0.052 : 0.025, 0.006, 0.012)),
          i % 5 === 0 ? chrome : ceramic,
