        new THREE.MeshPhysicalMaterial({
          color: '#506c85',
          metalness: 1,
          roughness: 0.21,
          clearcoat: 1,
          clearcoatRoughness: 0.06,
          iridescence: 1,
          iridescenceIOR: 1.32,
          iridescenceThicknessRange: [110, 530],
        }),
      );
