// Touch and sound choose a pose. Prism edge tilts the creature; heat lights
// its mouth. The local gesture value arrives in the same presentation frame,
// before a round trip to the audio host, so dragging never waits for an ack.
export default function creatureMotion() {
  let frame = 0;
  let lastSwitch = 0;
  let tilt = 0;
  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  return {
    evaluate(api, { time, delta }) {
      const energy = api.input('energy') ?? 0;
      const [hover, held, reducedMotion] = api.input('touch') ?? [0, 0, 0];
      const [gestureEdge, gestureHeat, dragging] = api.input('gesture') ?? [0, 0, 0];
      const edge = dragging ? gestureEdge : (api.input('edge') ?? 4800);
      const heat = dragging ? gestureHeat : (api.input('heat') ?? 8);
      const hot = clamp(heat / 40, 0, 1);
      const now = time * 1000;
      const pose = held
        ? 2
        : hover
          ? 1
          : hot > 0.68
            ? 2
            : energy > 0.16 && !reducedMotion
              ? Math.floor(now / 850) % 2
                ? 2
                : 1
              : 0;
      if (pose !== frame && now - lastSwitch > 180) {
        frame = pose;
        lastSwitch = now;
      }
      const response = reducedMotion ? 1 : 1 - Math.exp(-delta * 17);
      tilt +=
        (clamp(Math.log(Math.max(edge, 1) / 4800) * 0.035, -0.09, 0.09) +
          (held ? 0.025 : 0) -
          tilt) *
        response;
      return {
        frame,
        // Image coordinates turn clockwise; the scene's Y axis points up.
        rotation: (-tilt * 180) / Math.PI,
        glow: [
          0.08 + hot * 0.55 + energy * 0.2 + (held ? 0.15 : 0),
          0.79 - hot * 0.2,
          1 + energy * 0.35 + (held ? 0.45 : 0),
        ],
        controls: [edge, heat],
      };
    },
  };
}

import * as THREE from 'three';

// Nacre's placement and mouth light are project artwork. The image arriving
// here is selected and transformed by ordinary Manifold image nodes.
export default function oracleCreature() {
  return {
    create(api) {
      const scene = api.resource('scene');
      const { face } = scene;
      const resources = new Set();
      const keep = (resource) => {
        resources.add(resource);
        return resource;
      };
      const rig = new THREE.Group();
      const pose = new THREE.Group();
      pose.matrixAutoUpdate = false;
      rig.add(pose);
      scene.device.add(rig);
      const material = keep(
        new THREE.MeshBasicMaterial({
          color: '#ffffff',
          transparent: true,
          opacity: 0,
          alphaTest: 0.1,
          depthWrite: true,
          toneMapped: false,
        }),
      );
      const mouthMaterial = keep(
        new THREE.MeshBasicMaterial({
          color: '#db91ff',
          transparent: true,
          opacity: 0,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        }),
      );
      const art = new THREE.Mesh(keep(new THREE.PlaneGeometry(1, 1)), material);
      art.renderOrder = 6;
      const mouth = new THREE.Mesh(keep(new THREE.OctahedronGeometry(1, 1)), mouthMaterial);
      mouth.renderOrder = 7;
      const target = new THREE.Mesh(
        keep(new THREE.CircleGeometry(1, 32)),
        keep(new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })),
      );
      pose.add(art, mouth, target);
      let disposed = false,
        accepted = null;
      const unregister = scene.registerControlTarget('crab', target, () => Boolean(accepted));
      const textures = new Map();
      function load(path) {
        if (textures.has(path)) return;
        const entry = { texture: null, ready: false, error: false };
        textures.set(path, entry);
        Promise.resolve(api.assetUrl(path))
          .then((url) => {
            if (disposed || textures.get(path) !== entry) return;
            entry.texture = new THREE.TextureLoader().load(
              url,
              (texture) => {
                if (disposed || textures.get(path) !== entry) return;
                texture.colorSpace = THREE.SRGBColorSpace;
                entry.ready = true;
              },
              undefined,
              () => {
                entry.error = true;
              },
            );
          })
          .catch(() => {
            entry.error = true;
          });
      }
      return {
        update() {
          const image = api.input('image');
          const frames = api.input('frames')?.frames ?? [];
          // Warm the three authored poses; a larger edited sequence loads only
          // its selected frame and retains the last complete pose while waiting.
          const wanted = new Set([
            ...frames.slice(0, 3),
            ...(image ? [image.asset] : []),
            ...(image && accepted && frames.includes(accepted.asset) ? [accepted.asset] : []),
          ]);
          // Reordering or replacing images releases unused GPU textures.
          for (const [path, entry] of textures)
            if (!wanted.has(path)) {
              entry.texture?.dispose();
              textures.delete(path);
            }
          for (const path of wanted) load(path);
          const selected = image && textures.get(image.asset);
          if (!image || selected?.error || (accepted && !wanted.has(accepted.asset)))
            accepted = null;
          if (selected?.ready) accepted = image;
          else if (accepted && image) accepted = { ...image, asset: accepted.asset };
          rig.visible = Boolean(accepted);
          face.dataset.crabSprites = [...textures.values()].some((entry) => entry.error)
            ? 'unavailable'
            : wanted.size && [...textures.values()].every((entry) => entry.ready)
              ? 'ready'
              : 'loading';
          if (!accepted) return;
          const texture = textures.get(accepted.asset)?.texture;
          if (material.map !== texture) {
            material.map = texture;
            material.needsUpdate = true;
          }
          material.opacity = accepted.opacity;
          const { portrait, paneH } = scene.layout;
          const size = portrait ? 1.04 : 1.58;
          rig.position.set(portrait ? 0.82 : -0.34, portrait ? paneH / 2 - 1.34 : 1.16, 0.52);
          art.scale.set(size, size, 1);
          mouth.position.set(size * 0.3, -size * 0.11, 0.035);
          target.position.set(size * 0.3, -size * 0.11 + 0.25, 0.05);
          target.scale.setScalar(portrait ? 0.19 : 0.23);
          // Conjugate the image's Y-down affine transform into the Y-up scene.
          const [a, b, c, d, x, y] = accepted.transform;
          pose.matrix.set(a, -c, 0, x * size, -b, d, 0, -y * size, 0, 0, 1, 0, 0, 0, 0, 1);
          const [opacity, hue, scale] = api.input('glow') ?? [0.08, 0.79, 1];
          mouthMaterial.opacity = opacity * accepted.opacity;
          mouthMaterial.color.setHSL(hue, 0.88, 0.64);
          mouth.scale.setScalar((portrait ? 0.026 : 0.038) * scale);
          const [edge, heat] = api.input('controls') ?? [4800, 8];
          face.dataset.crabFrame = String(frames.indexOf(accepted.asset));
          face.dataset.crabEdge = edge.toFixed(1);
          face.dataset.crabHeat = heat.toFixed(1);
        },
        outputs: () => ({ image: accepted }),
        dispose() {
          if (disposed) return;
          disposed = true;
          unregister();
          scene.device.remove(rig);
          for (const entry of textures.values()) entry.texture?.dispose();
          textures.clear();
          for (const resource of resources) resource.dispose();
        },
      };
    },
  };
}

// The eye follows the pointer, glances with the sound and closes when Hold is
// engaged. These are presentation rules; they never schedule the audio engine.
export default function eyeMotion() {
  let openness = 0;
  let gaze = 0;
  let side = 0;
  let lastGlance = 0;
  let shutter = 0;
  return {
    evaluate(api, { time, delta }) {
      const energy = api.input('energy') ?? 0;
      const upper = api.input('upper') ?? 0;
      const phase = api.input('phase') ?? 0;
      const displacement = api.input('displacement') ?? 0;
      const holding = (api.input('hold') ?? 0) >= 0.5;
      const [cursor, present, reducedMotion] = api.input('pointer') ?? [0.5, 0, 0];
      const targetOpen = Math.min(
        1,
        Math.max(holding ? 0.88 : 0, present ? 0.6 : 0, (energy - 0.025) * 3.8),
      );
      openness +=
        (targetOpen - openness) * (1 - Math.exp(-delta * (targetOpen > openness ? 5 : 3)));
      const direction = present
        ? (cursor - 0.5) * 2
        : Math.sin(phase * 0.65) + displacement * 0.075 + upper * 0.35;
      const nextSide = direction > 0.08 ? 1 : 0;
      if (
        (present || !reducedMotion) &&
        time - lastGlance > (present ? 0.09 : 0.85) &&
        nextSide !== side
      ) {
        side = nextSide;
        lastGlance = time;
      }
      gaze += (side - gaze) * (1 - Math.exp(-delta * 12));
      const blink =
        !reducedMotion && openness > 0.15
          ? Math.pow(Math.max(0, Math.sin(phase * 1.83)), 36) * 0.94
          : 0;
      const visible = openness * (1 - blink);
      shutter = holding ? Math.min(1, shutter + delta * 7) : Math.max(0, shutter - delta * 8);
      if (!holding && energy > 0.12 && !reducedMotion) {
        shutter = Math.max(shutter, Math.pow(Math.max(0, Math.sin(phase * 2.3)), 28) * 0.9);
      }
      return {
        left: visible * (1 - gaze),
        right: visible * gaze,
        closed: shutter,
        light: [
          0.07 + Math.min(0.7, energy * 0.55 + upper * 0.35),
          0.49 + Math.min(0.3, upper * 0.3),
        ],
      };
    },
  };
}

import * as THREE from 'three';
import { imagePixelRect } from '@manifold/ui-web/diegetic';

// Three independently inspectable images share the relic's relief and location.
// Nacre owns this placement; ordinary image nodes own selection and opacity.
export default function relicEye() {
  return {
    create(api) {
      const scene = api.resource('scene');
      const relic = api.resource('relic');
      const { face } = scene;
      const rig = new THREE.Group();
      relic.surface.add(rig);
      const resources = new Set();
      const keep = (value) => {
        resources.add(value);
        return value;
      };
      const layers = ['left', 'right', 'closed'].map((name, index) => {
        const material = keep(
          new THREE.MeshBasicMaterial({
            color: '#ffffff',
            transparent: true,
            opacity: 0,
            alphaTest: 0.025,
            depthWrite: false,
            toneMapped: false,
          }),
        );
        if (name !== 'closed') material.onBeforeCompile = relic.applyRelief;
        const geometry = keep(
          new THREE.PlaneGeometry(1, 1, index < 2 ? 40 : 1, index < 2 ? 56 : 1),
        );
        const mesh = new THREE.Mesh(geometry, material);
        // Keep each image's transform separate from its authored placement.
        const placement = new THREE.Group();
        mesh.matrixAutoUpdate = false;
        placement.add(mesh);
        rig.add(placement);
        return { name, material, mesh, placement, accepted: null };
      });
      const lightMaterial = keep(
        new THREE.MeshBasicMaterial({
          color: '#a8faff',
          transparent: true,
          opacity: 0.08,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
          toneMapped: false,
        }),
      );
      const light = new THREE.Mesh(
        keep(new THREE.TorusGeometry(0.119, 0.006, 8, 48)),
        lightMaterial,
      );
      rig.add(light);
      const unregister = scene.registerControlTarget('eye', layers[2].mesh, () =>
        Boolean(layers[2].accepted),
      );
      const textures = new Map();
      let disposed = false;
      function load(path) {
        if (textures.has(path)) return;
        const entry = { texture: null, ready: false, error: false };
        textures.set(path, entry);
        Promise.resolve(api.assetUrl(path))
          .then((url) => {
            if (disposed || textures.get(path) !== entry) return;
            entry.texture = new THREE.TextureLoader().load(
              url,
              (texture) => {
                if (disposed || textures.get(path) !== entry) return;
                texture.colorSpace = THREE.SRGBColorSpace;
                entry.ready = true;
              },
              undefined,
              () => {
                entry.error = true;
              },
            );
          })
          .catch(() => {
            entry.error = true;
          });
      }
      return {
        update() {
          const inputs = layers.map((layer) => api.input(layer.name));
          const wanted = new Set();
          for (const [index, layer] of layers.entries()) {
            if (!inputs[index]) continue;
            wanted.add(inputs[index].asset);
            if (layer.accepted) wanted.add(layer.accepted.asset);
          }
          // At most three incoming and three last-complete images are resident.
          for (const [path, entry] of textures)
            if (!wanted.has(path)) {
              entry.texture?.dispose();
              textures.delete(path);
            }
          for (const path of wanted) load(path);
          const { width, height } = relic.layout;
          const eyeRect = imagePixelRect(163, 172, 94, 87, 330, 479, width, height);
          for (const [index, layer] of layers.entries()) {
            const image = inputs[index];
            const selected = image && textures.get(image.asset);
            if (!image) layer.accepted = null;
            else if (selected?.ready) layer.accepted = image;
            else if (layer.accepted) layer.accepted = { ...image, asset: layer.accepted.asset };
            const accepted = layer.accepted;
            layer.mesh.visible = Boolean(accepted);
            if (!accepted) continue;
            const texture = textures.get(accepted.asset).texture;
            if (layer.material.map !== texture) {
              layer.material.map = texture;
              layer.material.needsUpdate = true;
            }
            layer.material.opacity = accepted.opacity;
            const closed = layer.name === 'closed';
            const w = closed ? eyeRect.width : width;
            const h = closed ? eyeRect.height : height;
            layer.placement.position.set(
              closed ? eyeRect.x : 0,
              closed ? eyeRect.y : 0,
              closed ? 0.025 : 0.004 + index * 0.0003,
            );
            const [a, b, c, d, dx, dy] = accepted.transform;
            layer.mesh.matrix.set(
              a * w,
              -c * h,
              0,
              dx * w,
              -b * w,
              d * h,
              0,
              -dy * w,
              0,
              0,
              1,
              0,
              0,
              0,
              0,
              1,
            );
          }
          light.position.set(width * (0.606 - 0.5), height * (0.5 - 0.44), 0.012);
          light.scale.setScalar(width);
          const [opacity, hue] = api.input('light') ?? [0.07, 0.49];
          lightMaterial.opacity = opacity;
          lightMaterial.color.setHSL(hue, 0.9, 0.67);
          const left = layers[0].accepted?.opacity ?? 0;
          const right = layers[1].accepted?.opacity ?? 0;
          face.dataset.gazeOpen = (left + right).toFixed(3);
          face.dataset.gazeSide = (left + right ? right / (left + right) : 0).toFixed(3);
          face.dataset.eyeClosed = (layers[2].accepted?.opacity ?? 0).toFixed(3);
          const status = (images) =>
            images.some((image) => image && textures.get(image.asset)?.error)
              ? 'unavailable'
              : images.every((image) => image && textures.get(image.asset)?.ready)
                ? 'ready'
                : 'loading';
          face.dataset.gazeFrames = status(inputs.slice(0, 2));
          face.dataset.eyeSprite = status(inputs.slice(2));
          if ([...textures.values()].some((entry) => entry.error))
            throw new Error('An eye image could not be loaded; keeping its last complete image.');
        },
        outputs: () => ({ layers: layers.map((layer) => layer.accepted?.opacity ?? 0) }),
        dispose() {
          if (disposed) return;
          disposed = true;
          unregister();
          relic.surface.remove(rig);
          for (const entry of textures.values()) entry.texture?.dispose();
          textures.clear();
          for (const resource of resources) resource.dispose();
        },
      };
    },
  };
}

import * as THREE from 'three';
import { imageTexture, placeImage } from './image-texture.mjs';

// The engraving fills the cabinet plate. The frame, sockets and deck remain
// independent scene geometry; replacing this image changes only the engraving.
export default function cabinetArtwork() {
  return {
    create(api) {
      const scene = api.resource('scene');
      const texture = imageTexture(api);
      const material = new THREE.MeshBasicMaterial({
        color: '#ffffff',
        transparent: true,
        opacity: 0,
        depthWrite: false,
        toneMapped: false,
      });
      const geometry = new THREE.PlaneGeometry(1, 1);
      const mesh = new THREE.Mesh(geometry, material);
      const placement = new THREE.Group();
      placement.matrixAutoUpdate = false;
      placement.add(mesh);
      scene.device.add(placement);
      let accepted = null,
        disposed = false;
      return {
        update() {
          const result = texture.update(api.input('image'));
          accepted = result.image;
          scene.face.dataset.cabinetArt = result.status;
          mesh.visible = Boolean(accepted);
          if (accepted) {
            const { paneW, paneH } = scene.layout;
            const width = paneW - 0.28,
              height = paneH - 0.28;
            mesh.scale.set(width, height, 1);
            mesh.position.z = 0.176;
            placeImage(placement, accepted, width);
            if (material.map !== result.texture) {
              material.map = result.texture;
              material.needsUpdate = true;
            }
            material.opacity = 0.9 * accepted.opacity;
            // Preserve the original centre crop at the plate's aspect ratio.
            const pixels = result.texture.image;
            const imageAspect =
                pixels?.width && pixels?.height ? pixels.width / pixels.height : 768 / 512,
              plateAspect = width / height;
            if (plateAspect > imageAspect) {
              result.texture.repeat.set(1, imageAspect / plateAspect);
              result.texture.offset.set(0, (1 - result.texture.repeat.y) / 2);
            } else {
              result.texture.repeat.set(plateAspect / imageAspect, 1);
              result.texture.offset.set((1 - result.texture.repeat.x) / 2, 0);
            }
          }
          if (result.status === 'unavailable')
            throw Error('The cabinet image could not be loaded; keeping its last complete image.');
        },
        outputs: () => ({ image: accepted }),
        dispose() {
          if (disposed) return;
          disposed = true;
          scene.device.remove(placement);
          texture.dispose();
          geometry.dispose();
          material.dispose();
        },
      };
    },
  };
}

import * as THREE from 'three';
import { imageTexture, placeImage } from './image-texture.mjs';

// The photographed relic and its height map share one relief shader with the
// eye overlays. The mouth socket stays in the cabinet's authored layout.
export default function mouthRelic() {
  return {
    create(api) {
      const scene = api.resource('scene');
      const resources = new Set();
      const keep = (value) => {
        resources.add(value);
        return value;
      };
      const mouthRelicMaterial = keep(
        new THREE.MeshBasicMaterial({
          color: '#ffffff',
          transparent: true,
          opacity: 0,
          alphaTest: 0.025,
          depthWrite: false,
          toneMapped: false,
        }),
      );
      // PhotoCraft's grayscale plate is a real height field. Vertex relief and
      // depth gradients share this map; the jack aperture is masked from motion.
      const neutralDepth = keep(new THREE.DataTexture(new Uint8Array([128, 128, 128, 255]), 1, 1));
      neutralDepth.needsUpdate = true;
      const relicUniforms = {
        relicTime: { value: 0 },
        relicEnergy: { value: 0 },
        relicDepth: { value: neutralDepth },
      };
      mouthRelicMaterial.onBeforeCompile = (shader) => {
        Object.assign(shader.uniforms, relicUniforms);
        shader.vertexShader = shader.vertexShader.replace(
          '#include <common>',
          '#include <common>\nuniform sampler2D relicDepth;uniform float relicEnergy;',
        );
        shader.vertexShader = shader.vertexShader.replace(
          '#include <begin_vertex>',
          `#include <begin_vertex>
          float h=texture2D(relicDepth,uv).r;
          float anchor=smoothstep(.13,.30,distance(uv,vec2(.394,.353)));
          transformed.z+=anchor*(h-.35)*(.065+relicEnergy*.15);
        `,
        );
        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <common>',
          '#include <common>\nuniform sampler2D relicDepth;uniform float relicTime;uniform float relicEnergy;',
        );
        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <color_fragment>',
          `#include <color_fragment>
          #ifdef USE_MAP
          vec2 pixel=vec2(1.0/330.0,1.0/479.0);
          float west=texture2D(relicDepth,vMapUv-vec2(pixel.x,0.0)).r;
          float east=texture2D(relicDepth,vMapUv+vec2(pixel.x,0.0)).r;
          float south=texture2D(relicDepth,vMapUv-vec2(0.0,pixel.y)).r;
          float north=texture2D(relicDepth,vMapUv+vec2(0.0,pixel.y)).r;
          vec3 reliefNormal=normalize(vec3((west-east)*3.0,(south-north)*3.0,1.0));
          float distanceFromMouth=distance(vMapUv,vec2(.394,.353));
          float movingRelief=relicEnergy*smoothstep(.15,.37,distanceFromMouth)*.24;
          reliefNormal.xy+=movingRelief*vec2(sin(vMapUv.y*38.0+relicTime*2.0),cos(vMapUv.x*33.0-relicTime*1.6));
          vec2 parallax=reliefNormal.xy*relicEnergy*.024*smoothstep(.14,.32,distanceFromMouth);
          diffuseColor.rgb=mix(diffuseColor.rgb,texture2D(map,vMapUv+parallax).rgb,relicEnergy*.7);
          vec3 grazingLight=normalize(vec3(-.7+.5*sin(relicTime*.4),.38,.65));
          float foil=pow(max(dot(normalize(reliefNormal),grazingLight),0.0),7.0);
          diffuseColor.rgb+=vec3(.14,.35,.44)*foil*(.24+relicEnergy*1.8);
          #endif
        `,
        );
      };

      const artwork = imageTexture(api);
      const depth = imageTexture(api, THREE.NoColorSpace);
      const rig = new THREE.Group();
      const surface = new THREE.Group();
      surface.matrixAutoUpdate = false;
      rig.add(surface);
      const geometry = keep(new THREE.PlaneGeometry(1, 1, 40, 56));
      const mesh = new THREE.Mesh(geometry, mouthRelicMaterial);
      surface.add(mesh);
      scene.device.add(rig);
      const relic = api.exportResource('resource:nacre.relic', {
        surface,
        get layout() {
          return scene.relicLayout;
        },
        applyRelief: mouthRelicMaterial.onBeforeCompile,
      });
      let accepted = null,
        acceptedDepth = null,
        disposed = false;
      return {
        update() {
          const image = artwork.update(api.input('image'));
          const heightMap = depth.update(api.input('depth'));
          accepted = image.image;
          acceptedDepth = heightMap.image;
          scene.face.dataset.mouthRelic = image.status;
          scene.face.dataset.depthMap = heightMap.status;
          scene.face.dataset.reliefMotion = ((api.input('energy') ?? 0) * 0.15).toFixed(4);
          const { width, height, x, y } = scene.relicLayout;
          rig.position.set(x, y, 0.28);
          mesh.scale.set(width, height, 1);
          placeImage(surface, accepted, width);
          mesh.visible = Boolean(accepted);
          if (accepted) {
            if (mouthRelicMaterial.map !== image.texture) {
              mouthRelicMaterial.map = image.texture;
              mouthRelicMaterial.needsUpdate = true;
            }
            mouthRelicMaterial.opacity = 0.97 * accepted.opacity;
          }
          relicUniforms.relicDepth.value = heightMap.texture ?? neutralDepth;
          relicUniforms.relicTime.value = api.input('phase') ?? 0;
          relicUniforms.relicEnergy.value = api.input('energy') ?? 0;
          if (image.status === 'unavailable' || heightMap.status === 'unavailable')
            throw Error('A relic image could not be loaded; keeping its last complete image.');
          // The map samples the source UVs, independent of scene placement.
          // Do not silently ignore transforms on a height-map input.
          if (
            heightMap.status === 'ready' &&
            (acceptedDepth.opacity !== 1 ||
              acceptedDepth.transform.some((value, i) => value !== [1, 0, 0, 1, 0, 0][i]))
          )
            throw Error(
              'Relic depth needs an untransformed image; place the relic through its artwork input.',
            );
        },
        outputs: () => ({ relic, image: accepted, depth: acceptedDepth }),
        dispose() {
          if (disposed) return;
          disposed = true;
          scene.device.remove(rig);
          artwork.dispose();
          depth.dispose();
          for (const resource of resources) resource.dispose();
        },
      };
    },
  };
}

import * as THREE from 'three';

// One image input owns its requested texture and its last complete texture.
// The caller chooses colour or data sampling; decoded pixels never enter the graph.
export function imageTexture(api, colorSpace = THREE.SRGBColorSpace) {
  const textures = new Map();
  let accepted = null,
    disposed = false;
  function load(path) {
    if (textures.has(path)) return;
    const entry = { texture: null, ready: false, error: false };
    textures.set(path, entry);
    Promise.resolve()
      .then(() => api.assetUrl(path))
      .then((url) => {
        if (disposed || textures.get(path) !== entry) return;
        entry.texture = new THREE.TextureLoader().load(
          url,
          (texture) => {
            if (disposed || textures.get(path) !== entry) return;
            texture.colorSpace = colorSpace;
            entry.ready = true;
          },
          undefined,
          () => {
            entry.error = true;
          },
        );
      })
      .catch(() => {
        entry.error = true;
      });
  }
  return {
    update(image) {
      if (disposed) return { image: null, texture: null, status: 'disconnected' };
      if (!image) accepted = null;
      else {
        load(image.asset);
        if (textures.get(image.asset).ready) accepted = image;
        else if (accepted) accepted = { ...image, asset: accepted.asset };
      }
      const wanted = new Set([image?.asset, accepted?.asset]);
      for (const [path, entry] of textures)
        if (!wanted.has(path)) {
          entry.texture?.dispose();
          textures.delete(path);
        }
      return {
        image: accepted,
        texture: accepted ? textures.get(accepted.asset).texture : null,
        status: !image
          ? 'disconnected'
          : textures.get(image.asset).error
            ? 'unavailable'
            : textures.get(image.asset).ready
              ? 'ready'
              : 'loading',
      };
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      for (const entry of textures.values()) entry.texture?.dispose();
      textures.clear();
      accepted = null;
    },
  };
}

// Image coordinates point down; the scene points up. Translation uses image width.
export function placeImage(group, image, width) {
  const [a, b, c, d, x, y] = image?.transform ?? [1, 0, 0, 1, 0, 0];
  group.matrix.set(a, -c, 0, x * width, -b, d, 0, -y * width, 0, 0, 1, 0, 0, 0, 0, 1);
}

// Local touch previews lead host acknowledgements. Each output names the
// physical part it moves; the scene object owns wrist placement and clearance.
export default function handMotion() {
  let rotation = 0,
    tilt = 0,
    ringRotation = 0,
    ringScale = 1,
    grainRotation = 0;
  return {
    evaluate(api, { delta }) {
      const [hover, held, reduced] = api.input('touch') ?? [0, 0, 0];
      const [gestureScatter, gestureGrain, dragging] = api.input('gesture') ?? [0, 0, 0];
      const scatter = dragging ? gestureScatter : (api.input('scatter') ?? 0.28);
      const grainSize = dragging ? gestureGrain : (api.input('grainSize') ?? 85);
      const grain = Math.max(0, Math.min(1, (grainSize - 20) / 230));
      const response = reduced ? 1 : 1 - Math.exp(-delta * 17);
      rotation +=
        ((scatter - 0.28) * 0.25 + (held ? 0.028 : hover ? 0.016 : 0) - rotation) * response;
      tilt += (((grainSize - 85) / 165) * 0.12 - tilt) * response;
      ringRotation += ((scatter - 0.28) * 0.8 - ringRotation) * response;
      ringScale += ((held ? 1.12 : hover ? 1.08 : 1) - ringScale) * response;
      grainRotation += ((grain - 0.28) * 0.95 - grainRotation) * response;
      return {
        rotation,
        tilt,
        ringRotation,
        ringScale,
        grainRotation,
        response,
        height: 0.195 + (hover || held ? 0.016 : 0) - (held ? 0.028 : 0),
        glow: 0.08 + (held ? 0.9 : hover ? 0.52 : 0) + (api.input('energy') ?? 0) * 0.1,
        grain,
        scatter,
      };
    },
  };
}

import * as THREE from 'three';

// The image nodes choose and transform the actual cutouts. This object owns
// their wrist pivot, shallow relief, engraved bearings and silhouette hit test.
export default function crystalHand() {
  return {
    create(api) {
      const scene = api.resource('scene');
      const { face } = scene;
      const { chrome } = scene.materials;
      const resources = new Set();
      const keep = (value) => {
        resources.add(value);
        return value;
      };
      const heartUniforms = {
        heartTime: { value: 0 },
        heartEnergy: { value: 0 },
        heartScatter: { value: 0 },
        heartGrain: { value: 0 },
      };
      const heartMaterial = keep(
        new THREE.MeshBasicMaterial({
          color: '#ffffff',
          transparent: true,
          opacity: 1,
          alphaTest: 0.1,
          depthWrite: true,
          toneMapped: false,
        }),
      );
      heartMaterial.onBeforeCompile = (shader) => {
        Object.assign(shader.uniforms, heartUniforms);
        shader.vertexShader = shader.vertexShader.replace(
          '#include <common>',
          '#include <common>\nuniform float heartEnergy;uniform float heartScatter;uniform float heartGrain;',
        );
        shader.vertexShader = shader.vertexShader.replace(
          '#include <begin_vertex>',
          `#include <begin_vertex>
          float heart=exp(-dot((uv-vec2(.36,.67))*vec2(2.1,2.5),(uv-vec2(.36,.67))*vec2(2.1,2.5))*5.0);
          transformed.z+=heart*(.006+.015*heartEnergy+.013*heartScatter+.008*heartGrain);
        `,
        );
        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <common>',
          '#include <common>\nuniform float heartTime;uniform float heartEnergy;uniform float heartScatter;uniform float heartGrain;',
        );
        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <color_fragment>',
          `#include <color_fragment>
          #ifdef USE_MAP
          float heart=exp(-dot((vMapUv-vec2(.36,.67))*vec2(2.1,2.5),(vMapUv-vec2(.36,.67))*vec2(2.1,2.5))*5.0);
          float facets=pow(max(0.0,sin(vMapUv.x*48.0+vMapUv.y*21.0-heartTime*(.4+heartGrain*1.5))),16.0);
          vec3 spectrum=.5+.5*cos(6.2831853*(vMapUv.y*.8+heartScatter*.2+heartTime*.025+vec3(0.0,.33,.67)));
          diffuseColor.rgb+=spectrum*heart*(facets*.10+heartEnergy*(.07+heartScatter*.18));
          #endif
        `,
        );
      };
      // A separate photographed graft covers every grasp pose. Its centre is
      // cut out in the shader: the real 3D ferrule remains visible in the hole
      // while porcelain, gold and tendons overhang its edge.
      const wristGraftMaterial = keep(
        new THREE.MeshBasicMaterial({
          color: '#ffffff',
          transparent: true,
          opacity: 0.98,
          alphaTest: 0.025,
          depthTest: false,
          depthWrite: false,
          toneMapped: false,
        }),
      );
      wristGraftMaterial.onBeforeCompile = (shader) => {
        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <color_fragment>',
          `#include <color_fragment>
          #ifdef USE_MAP
          float surround=1.0-smoothstep(.76,1.0,length((vMapUv-vec2(.89,.11))/vec2(.23,.21)));
          float aperture=smoothstep(.70,1.05,length((vMapUv-vec2(.895,.067))/vec2(.061,.055)));
          diffuseColor.a*=surround*aperture;
          #endif
        `,
        );
      };

      const heartRig = new THREE.Group();
      heartRig.position.z = 0.195;
      const pose = new THREE.Group();
      pose.matrixAutoUpdate = false;
      heartRig.add(pose);
      const geometry = keep(new THREE.PlaneGeometry(1, 1, 24, 36));
      const heartArt = new THREE.Mesh(geometry, heartMaterial);
      pose.add(heartArt);
      const graftPose = new THREE.Group();
      graftPose.matrixAutoUpdate = false;
      heartRig.add(graftPose);
      const graft = new THREE.Mesh(geometry, wristGraftMaterial);
      graft.renderOrder = 10;
      graftPose.add(graft);
      const heartTarget = new THREE.Mesh(
        keep(new THREE.CircleGeometry(1, 32)),
        keep(new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })),
      );
      heartRig.add(heartTarget);
      // Two engraved bearings expose Scatter and Grain as physical settings.
      const heartGimbal = new THREE.Group();
      heartGimbal.position.copy(heartTarget.position);
      heartGimbal.position.z = 0.075;
      heartRig.add(heartGimbal);
      const jewelMetal = keep(
        new THREE.MeshPhysicalMaterial({
          color: '#e7c9a0',
          metalness: 0.9,
          roughness: 0.18,
          emissive: '#794b9a',
          emissiveIntensity: 0.08,
          clearcoat: 1,
        }),
      );
      for (const start of [0.15, Math.PI + 0.15]) {
        const arc = new THREE.Mesh(
          keep(new THREE.TorusGeometry(0.205, 0.007, 6, 44, Math.PI * 0.72)),
          jewelMetal,
        );
        arc.rotation.z = start;
        heartGimbal.add(arc);
      }
      const heartGrainDial = new THREE.Group();
      heartGimbal.add(heartGrainDial);
      for (const start of [0, Math.PI]) {
        const arc = new THREE.Mesh(
          keep(new THREE.TorusGeometry(0.153, 0.004, 6, 36, Math.PI * 0.38)),
          chrome,
        );
        arc.rotation.z = start;
        arc.position.z = 0.004;
        heartGrainDial.add(arc);
      }

      const textures = new Map();
      let accepted = null,
        acceptedGraft = null,
        disposed = false;
      const corner = new THREE.Vector3();
      const hitWidth = 128,
        hitHeight = 186;
      function load(path) {
        if (textures.has(path)) return;
        const entry = { texture: null, ready: false, error: false, pixels: null };
        textures.set(path, entry);
        Promise.resolve(api.assetUrl(path))
          .then((url) => {
            if (disposed || textures.get(path) !== entry) return;
            entry.texture = new THREE.TextureLoader().load(
              url,
              (texture) => {
                if (disposed || textures.get(path) !== entry) return;
                texture.colorSpace = THREE.SRGBColorSpace;
                entry.ready = true;
                try {
                  const canvas = document.createElement('canvas');
                  canvas.width = hitWidth;
                  canvas.height = hitHeight;
                  const context = canvas.getContext('2d', { willReadFrequently: true });
                  context.drawImage(texture.image, 0, 0, hitWidth, hitHeight);
                  entry.pixels = context.getImageData(0, 0, hitWidth, hitHeight).data;
                } catch {
                  /* The crystal circle remains usable without pixel access. */
                }
              },
              undefined,
              () => {
                entry.error = true;
              },
            );
          })
          .catch(() => {
            entry.error = true;
          });
      }
      function hitTest(raycaster) {
        const imageHit = raycaster.intersectObject(heartArt, false)[0];
        const pixels = accepted && textures.get(accepted.asset)?.pixels;
        if (imageHit && pixels) {
          const x = Math.max(0, Math.min(hitWidth - 1, Math.floor(imageHit.uv.x * hitWidth)));
          const y = Math.max(
            0,
            Math.min(hitHeight - 1, Math.floor((1 - imageHit.uv.y) * hitHeight)),
          );
          return pixels[(y * hitWidth + x) * 4 + 3] > 64;
        }
        return raycaster.intersectObject(heartTarget, false).length > 0;
      }
      function affine(group, image, width) {
        const [a, b, c, d, x, y] = image.transform;
        group.matrix.set(a, -c, 0, x * width, -b, d, 0, -y * width, 0, 0, 1, 0, 0, 0, 0, 1);
      }
      const hand = api.exportResource('resource:nacre.hand', {
        rig: heartRig,
        anchor: heartTarget.position,
        ready: () => Boolean(accepted),
      });
      scene.device.add(heartRig);
      const unregister = scene.registerControlTarget(
        'heart',
        heartArt,
        () => Boolean(accepted),
        hitTest,
      );
      return {
        update() {
          const image = api.input('image');
          const graftImage = api.input('graft');
          const frames = api.input('frames')?.frames ?? [];
          const wanted = new Set([
            ...frames.slice(0, 3),
            ...(image ? [image.asset, ...(accepted ? [accepted.asset] : [])] : []),
            ...(graftImage
              ? [graftImage.asset, ...(acceptedGraft ? [acceptedGraft.asset] : [])]
              : []),
          ]);
          for (const [path, entry] of textures)
            if (!wanted.has(path)) {
              entry.texture?.dispose();
              textures.delete(path);
            }
          for (const path of wanted) load(path);
          const accept = (next, previous) =>
            !next
              ? null
              : textures.get(next.asset)?.ready
                ? next
                : previous
                  ? { ...next, asset: previous.asset }
                  : null;
          accepted = accept(image, accepted);
          acceptedGraft = accept(graftImage, acceptedGraft);
          const status = (paths) =>
            paths.some((path) => textures.get(path)?.error)
              ? 'unavailable'
              : paths.length && paths.every((path) => textures.get(path)?.ready)
                ? 'ready'
                : 'loading';
          face.dataset.handSprites = status(frames.slice(0, 3));
          face.dataset.heartArt = status(image ? [image.asset] : []);
          face.dataset.wristGraft = status(graftImage ? [graftImage.asset] : []);
          face.dataset.handHit =
            accepted && textures.get(accepted.asset)?.pixels ? 'silhouette' : 'crystal';
          heartRig.visible = Boolean(accepted);
          graft.visible = Boolean(acceptedGraft);
          // A hidden/cold Presenter may not have measured its pane yet.
          // This is expected preparation, not a failed script to latch.
          if (!scene.handLayout) return;
          const { width, height, x, y, wristX, wristY, portrait } = scene.handLayout;
          heartRig.position.x = x + wristX;
          heartRig.position.y = y + wristY;
          heartArt.position.set(-wristX, -wristY, 0);
          heartArt.scale.set(width, height, 1);
          graft.position.set(-wristX - width * 0.032, -wristY + height * 0.011, 0.004);
          graft.scale.set(width, height, 1);
          for (const [mesh, group, value, opacity] of [
            [heartArt, pose, accepted, 1],
            [graft, graftPose, acceptedGraft, 0.98],
          ]) {
            if (!value) continue;
            const texture = textures.get(value.asset).texture;
            if (mesh.material.map !== texture) {
              mesh.material.map = texture;
              mesh.material.needsUpdate = true;
            }
            mesh.material.opacity = value.opacity * opacity;
            affine(group, value, width);
          }
          heartTarget.position.set(-wristX - width * 0.14, -wristY + height * 0.28, 0.06);
          heartTarget.scale.setScalar(portrait ? 0.18 : 0.24);
          heartGimbal.position.copy(heartTarget.position);
          heartGimbal.position.z = 0.075;
          heartRig.rotation.set(0, api.input('tilt') ?? 0, api.input('rotation') ?? 0);
          heartRig.position.z +=
            ((api.input('height') ?? 0.195) - heartRig.position.z) * (api.input('response') ?? 1);
          // Keep all four transformed corners above the cabinet (z=.176),
          // retaining normal depth testing against the socket and control deck.
          let back = Infinity;
          for (let i = 0; i < 4; i++) {
            corner
              .set((i & 1 ? 0.5 : -0.5) * width, (i & 2 ? 0.5 : -0.5) * height, 0)
              .add(heartArt.position)
              .applyMatrix4(pose.matrix)
              .applyQuaternion(heartRig.quaternion);
            back = Math.min(back, corner.z);
          }
          heartRig.position.z = Math.max(heartRig.position.z, 0.182 - back);
          heartGimbal.rotation.z = api.input('ringRotation') ?? 0;
          heartGimbal.scale.set(api.input('ringScale') ?? 1, api.input('ringScale') ?? 1, 1);
          heartGrainDial.rotation.z = api.input('grainRotation') ?? 0;
          jewelMetal.emissiveIntensity = api.input('glow') ?? 0.08;
          heartUniforms.heartTime.value = api.input('phase') ?? 0;
          heartUniforms.heartEnergy.value = api.input('energy') ?? 0;
          heartUniforms.heartScatter.value = api.input('scatter') ?? 0.28;
          heartUniforms.heartGrain.value = api.input('grain') ?? 0.28;
          face.dataset.graspFrame = String(accepted ? frames.indexOf(accepted.asset) : -1);
          face.dataset.handAngle = heartRig.rotation.z.toFixed(4);
          face.dataset.jewelAngle = heartGimbal.rotation.z.toFixed(4);
          face.dataset.grainDialAngle = heartGrainDial.rotation.z.toFixed(4);
          if ([image, graftImage].some((value) => value && textures.get(value.asset)?.error))
            throw new Error('A hand image could not be loaded; keeping its last complete image.');
        },
        outputs: () => ({ hand, image: accepted }),
        dispose() {
          if (disposed) return;
          disposed = true;
          unregister();
          scene.device.remove(heartRig);
          for (const entry of textures.values()) entry.texture?.dispose();
          textures.clear();
          for (const resource of resources) resource.dispose();
        },
      };
    },
  };
}

// Transmutation turns the collar; Afterimage opens its grasp and expands it.
export default function haloMotion() {
  let rotation = 0,
    scale = 1;
  return {
    evaluate(api, { delta }) {
      const [hover, held, reduced] = api.input('touch') ?? [0, 0, 0];
      const [gestureMix, gestureAfterimage, dragging] = api.input('gesture') ?? [0, 0, 0];
      const mix = dragging ? gestureMix : (api.input('mix') ?? 0.64);
      const afterimage = dragging ? gestureAfterimage : (api.input('afterimage') ?? 0.22);
      const response = reduced ? 1 : 1 - Math.exp(-delta * 17);
      rotation += ((mix - 0.64) * 0.75 - rotation) * response;
      scale += (0.93 + afterimage * 0.2 + (held ? 0.035 : hover ? 0.015 : 0) - scale) * response;
      return {
        frame: afterimage >= 0.7 ? 2 : afterimage >= 0.35 ? 1 : 0,
        rotation,
        scale,
        glow: 0.1 + (held ? 0.45 : hover ? 0.22 : 0) + (api.input('energy') ?? 0) * 0.1,
      };
    },
  };
}

import * as THREE from 'three';

// A separate draggable collar attaches to the real hand's wrist assembly.
export default function memoryHalo() {
  return {
    create(api) {
      const scene = api.resource('scene');
      const hand = api.resource('hand');
      const { spectralCrystal } = scene.materials;
      const resources = new Set();
      const keep = (value) => {
        resources.add(value);
        return value;
      };
      // The outer split collar is a second two-axis surface: turning it blends
      // the effect, while pulling it changes how much spectral memory remains.
      const memoryHalo = new THREE.Group();
      memoryHalo.position.copy(hand.anchor);
      memoryHalo.position.z = 0.07;
      hand.rig.add(memoryHalo);
      const haloMetal = keep(
        new THREE.MeshPhysicalMaterial({
          color: '#dbabd6',
          metalness: 0.85,
          roughness: 0.18,
          transparent: true,
          opacity: 0.55,
          emissive: '#57225f',
          emissiveIntensity: 0.1,
          clearcoat: 1,
        }),
      );
      for (const start of [0.2, Math.PI + 0.2]) {
        const arc = new THREE.Mesh(
          keep(new THREE.TorusGeometry(0.35, 0.009, 8, 64, Math.PI * 0.62)),
          haloMetal,
        );
        arc.rotation.z = start;
        memoryHalo.add(arc);
      }
      const haloIndex = new THREE.Mesh(
        keep(new THREE.OctahedronGeometry(0.028, 0)),
        spectralCrystal,
      );
      haloIndex.position.set(0, 0.35, 0.012);
      memoryHalo.add(haloIndex);

      const target = new THREE.Mesh(
        keep(new THREE.RingGeometry(0.245, 0.43, 64)),
        keep(new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })),
      );
      hand.rig.add(target);
      const unregister = scene.registerControlTarget('halo', target, hand.ready);
      let disposed = false;
      return {
        update() {
          target.position.copy(hand.anchor);
          target.position.z = 0.08;
          memoryHalo.position.copy(hand.anchor);
          memoryHalo.position.z = 0.07;
          memoryHalo.rotation.z = api.input('rotation') ?? 0;
          const scale = api.input('scale') ?? 1;
          memoryHalo.scale.set(scale, scale, 1);
          haloMetal.emissiveIntensity = api.input('glow') ?? 0.1;
          scene.face.dataset.memoryHaloAngle = memoryHalo.rotation.z.toFixed(4);
          scene.face.dataset.memoryHaloScale = scale.toFixed(4);
        },
        outputs: () => ({ rotation: memoryHalo.rotation.z }),
        dispose() {
          if (disposed) return;
          disposed = true;
          unregister();
          hand.rig.remove(memoryHalo, target);
          for (const resource of resources) resource.dispose();
        },
      };
    },
  };
}

